//! Side-by-side native-grid products, L2 successes averaged only inside matching AC windows.
use anyhow::{Result,ensure};use rustplotlib::*;use chrono::NaiveDateTime;use hdf5::types::FixedAscii;use std::{path::Path,fs};
fn main()->Result<()>{let a:Vec<_>=std::env::args().collect();let ac=hdf5::File::open(&a[1])?;let l=hdf5::File::open(&a[2])?;let out=Path::new(&a[3]);fs::create_dir_all(out)?;let ds=l.dataset("Fittedparameter")?;let sh=ds.shape();ensure!(sh.len()==4&&sh[3]==4,"L2 dimensions");let(nb,nt,nr)=(sh[0],sh[1],sh[2]);let p=ds.read_raw::<f32>()?;let state=l.dataset("Fitstate")?.read_raw::<f32>()?;let geo=l.dataset("GEO")?.read_raw::<f64>()?;let dirs=l.dataset("Beamdir")?.read_raw::<f64>()?;let times=l.dataset("Time")?.read_raw::<FixedAscii<20>>()?;
let stats=hdf5::File::create(out.join("matched-comparison.h5"))?;
for name in ac.member_names()?{let g=ac.group(&name)?;let bits:Vec<_>=name.split('-').collect();let az=bits[1].trim_start_matches("az").parse::<f64>()?*360./65536.;let el=bits[2].trim_start_matches("el").parse::<f64>()?*360./65536.;let b=(0..nb).min_by(|i,j|((dirs[i*2]-az).abs()+(dirs[i*2+1]-el).abs()).total_cmp(&((dirs[j*2]-az).abs()+(dirs[j*2+1]-el).abs()))).unwrap();ensure!((dirs[b*2+1]-el).abs()<0.2,"beam");let x=g.dataset("local_hours")?.read_raw::<f64>()?;let z=g.dataset("altitude_edges_km")?.read_raw::<f64>()?;let n=x.len()-1;let mut h=vec![0.;nr];for r in 0..nr{let mut v:Vec<_>=(0..nt).map(|t|geo[((b*nt+t)*nr+r)*3+2]).filter(|v|v.is_finite()).collect();v.sort_by(f64::total_cmp);h[r]=v[v.len()/2];}let mut ze=vec![h[0]-(h[1]-h[0])/2.];ze.extend(h.windows(2).map(|v|(v[0]+v[1])/2.));ze.push(h[nr-1]+(h[nr-1]-h[nr-2])/2.);
let sg=stats.create_group(&name)?;
let fields=[("ne_m3",r"$N_e$ (m$^{-3}$)",[1e10,1e12],Normalization::Log,0usize),("ti_k",r"$T_i$ (K)",[150.,3000.],Normalization::Linear,1),("te_k",r"$T_e$ (K)",[150.,6000.],Normalization::Linear,2),("vi_m_s",r"$v_i$ (m/s)",[-1000.,1000.],Normalization::Linear,3)];let mut fig=Figure::new(IntendedUse::ArticleWide);fig.width_mm=230.;fig.height_mm=215.;fig.latex.cache=out.join("latex-cache");fig.raster_dpi=300.;
for(q,(key,label,lim,norm,col))in fields.iter().enumerate(){let va=g.dataset(key)?.read_raw::<f64>()?;let mut vl=vec![f64::NAN;nr*n];let mut sums=vec![0.;nr*n];let mut counts=vec![0usize;nr*n];for t in 0..nt{let Ok(ts)=NaiveDateTime::parse_from_str(times[b*nt+t].as_str().trim(),"%d-%b-%Y %H:%M:%S") else {continue;};let hour=((ts.and_utc().timestamp()+28800)as f64-1759708800.)/3600.; // 2025-10-06 local-calendar epoch; UTC L2 timestamps shifted for display.

if hour<x[0]||hour>=*x.last().unwrap(){continue;}let k=x.partition_point(|v|*v<=hour)-1;for r in 0..nr{let ix=(b*nt+t)*nr+r;let value=p[ix*4+col]as f64;if state[ix]==0.&&value.is_finite()&&(*col==3||value>0.){sums[r*n+k]+=value;counts[r*n+k]+=1;}}}for i in 0..vl.len(){if counts[i]>0{vl[i]=sums[i]/counts[i]as f64;}}
// Show L2 only where this beam has a completed AC window.
for t in 0..n{if !(0..z.len()-1).any(|r|va[r*n+t].is_finite()){for r in 0..nr{vl[r*n+t]=f64::NAN;}}}
let mut residuals=vec![];for r in 0..nr {if !(200.0..=600.0).contains(&h[r]){continue;}let k=(0..z.len()-1).min_by(|i,j|(((z[*i]+z[*i+1])/2.-h[r]).abs()).total_cmp(&(((z[*j]+z[*j+1])/2.-h[r]).abs()))).unwrap();if ((z[k]+z[k+1])/2.-h[r]).abs()>15.{continue;}for t in 0..n{let aa=va[k*n+t];let bb=vl[r*n+t];if aa.is_finite()&&bb.is_finite(){residuals.push(if q==0{aa/bb}else{aa-bb});}}}residuals.sort_by(f64::total_cmp);if !residuals.is_empty(){let med=residuals[residuals.len()/2];sg.new_dataset_builder().with_data(&residuals).create(*key)?;println!("{name} {key} matched={} median={} {}",residuals.len(),med,if q==0{"ratio"}else{"AC-minus-L2"});}
let scale=fig.scale(Scale::new(*lim,*norm,ColorMap::turbo())?);for(c,(zz,values))in [(z.clone(),va),(ze.clone(),vl)].into_iter().enumerate(){let mut ax=Axes::new([x[0],*x.last().unwrap()],[100.,1000.],if q==3{"China local time (UTC+8)"}else{""},if c==0{"Altitude (km)"}else{""});ax.yticks=vec![100.,400.,700.,1000.];ax.xticks.clear();let interval=if x.last().unwrap()-x[0]>6.{4.}else{2.};let mut tick=(x[0]/interval).ceil()*interval;while tick<=*x.last().unwrap(){ax.xticks.push(tick);tick+=interval;}ax.xticklabels=Some(ax.xticks.iter().map(|h|format!("{:02}:00",*h as i32%24)).collect());if q<3{ax.show_x_axis=false;}if c==1{ax.yticklabels=Some(vec!["100".into(),"400".into(),"700".into(),"1000".into()]);}let rect=Rect::new(22.+c as f64*89.,20.+q as f64*43.,80.,35.);let mut panel=Panel::new(rect,ax);panel.pcolormesh(x.clone(),zz,values,scale)?;fig.panels.push(panel);}fig.colorbars.push(Colorbar::new(Rect::new(195.,20.+q as f64*43.,2.5,35.),scale,"",vec![]));for(v,y)in[(lim[0],55.+q as f64*43.),(lim[1],20.+q as f64*43.)]{let txt=if q==0{format!("$10^{{{:.0}}}$",v.log10())}else{format!("{v:.0}")};fig.labels.push(Label::new(txt,207.,y));}let mut lab=Label::new(*label,221.,37.5+q as f64*43.);lab.rotation=-90.;fig.labels.push(lab);}
fig.labels.push(Label::new("AC refit",62.,10.));fig.labels.push(Label::new("Supplied L2",151.,10.));fig.labels.push(Label::new(format!("Azimuth {az:.1} degrees; elevation {el:.1} degrees; matched 30-minute windows"),115.,198.));fig.labels.push(Label::new("L2 successful fits averaged in time; native altitude grids retained; velocity signs uncalibrated",115.,207.));fig.save(out.join(format!("{name}-l2.png")))?;
}Ok(())}
